/* ERZEUGT — NICHT VON HAND AENDERN.
 *
 * Quelle:  neos-compendium, dist/plans/duenger_plan.csv
 * Erzeugt: build/export_fx_duenger.py  ·  2026-08-04
 *
 * Produktscharfer Duengerplan aus den Anbautelegrammen. Er loest die
 * Naehrstoff-Mischpreise (fert.n/p/k) fuer die zugeordneten Kulturen ab.
 * Wer eine Zahl hier aendern will, aendert sie im Kompendium und exportiert
 * neu — sonst laufen die beiden Staende auseinander, und das faellt niemandem auf.
 */

/** Ein Duengerprodukt mit Preis je kg Ware und dem Belegstatus dieses Preises. */
export interface DuengerProdukt {
  kurz: string; name: string;
  /** CENT je kg Ware. */
  preisCentKg: number;
  evidence: string;
}

/** Eine Gabe: ein Produkt, eine Warenmenge, die Naehrstoffe, die damit kommen. */
export interface DuengerGabe {
  cropId: string; cfgId: string;
  /** Anteil dieser Konfiguration an der Kultur (Mischpositionen). */
  anteil: number;
  nr: number; kwVon: number; kwBis: number;
  massnahme: string; kurz: string;
  wareKgHa: number;
  n: number; p2o5: number; k2o: number; mgo: number; cao: number; so3: number;
  mikro?: string; mikroKgHa?: number;
  eurHa: number;
  evidence: string;
  /** true, wenn die Gabe ueber die Fertigation laeuft (kein Streuer-Ueberfahrt). */
  fertigation: boolean;
}

